SELECT p.gender, CAST(COUNT(DISTINCT CASE WHEN d.icd_code = 'I64' AND p.age BETWEEN 48 AND 58 AND d.seq_num = 1 AND i.los <= 5 THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS mortality_rate_icu_los_le5, CAST(COUNT(DISTINCT CASE WHEN d.icd_code = 'I64' AND p.age BETWEEN 48 AND 58 AND d.seq_num = 1 AND i.los > 5 THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS mortality_rate_icu_los_gt5, CAST(COUNT(DISTINCT CASE WHEN d.icd_code = 'I64' AND p.age BETWEEN 48 AND 58 AND d.seq_num = 1 AND i.los <= 5 THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) * 100 AS percentage_icu_los_le5, CAST(COUNT(DISTINCT CASE WHEN d.icd_code = 'I64' AND p.age BETWEEN 48 AND 58 AND d.seq_num = 1 AND i.los > 5 THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) * 100 AS percentage_icu_los_gt5, (percentage_icu_los_le5 - percentage_icu_los_gt5) / NULLIF(percentage_icu_los_le5, 0) AS percentage_change_icu_los_le5_gt5, (percentage_icu_los_gt5 - percentage_icu_los_le5) / NULLIF(percentage_icu_los_gt5, 0) AS percentage_change_icu_los_gt5_le5 FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id JOIN icustays i ON a.subject_id = i.subject_id WHERE p.gender = 'F' GROUP BY p.gender;